"""Bundle the UI into one HTML document, without a JavaScript build tool.

Edit web/index.template.html, web/app.js and web/styles.css, then run this script.
The generated web/index.html can render without separate asset requests.
"""

import argparse
import base64
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
WEB = ROOT / "web"


def data_uri(path: Path, media_type: str):
    return f"data:{media_type};base64," + base64.b64encode(path.read_bytes()).decode("ascii")


def replace_once(document: str, old: str, new: str):
    if document.count(old) != 1:
        raise ValueError(f"Expected one template marker: {old}")
    return document.replace(old, new, 1)


def bundle():
    document = (WEB / "index.template.html").read_text()
    license_text = (WEB / "vendor/leaflet/LICENSE").read_text()
    document = replace_once(
        document,
        'href="favicon.svg"',
        f'href="{data_uri(WEB / "favicon.svg", "image/svg+xml")}"',
    )
    leaflet_css = (WEB / "vendor/leaflet/leaflet.css").read_text()
    for name in ("layers.png", "layers-2x.png", "marker-icon.png"):
        leaflet_css = leaflet_css.replace(
            f"url(images/{name})",
            f"url({data_uri(WEB / 'vendor/leaflet/images' / name, 'image/png')})",
        )
    for name, css in (
        ("vendor/leaflet/leaflet.css", leaflet_css),
        ("styles.css", (WEB / "styles.css").read_text()),
    ):
        if "</style" in css.lower():
            raise ValueError(f"Unexpected closing style tag in {name}")
        document = replace_once(
            document,
            f'<link rel="stylesheet" href="{name}" />',
            f'<style data-source="{name}">\n{css}\n</style>',
        )
    scripts = []
    for name in ("vendor/leaflet/leaflet.js", "app.js"):
        javascript = (WEB / name).read_text()
        javascript = re.sub(r"^//# sourceMappingURL=.*$", "", javascript, flags=re.MULTILINE)
        if "</script" in javascript.lower():
            raise ValueError(f"Unexpected closing script tag in {name}")
        document = replace_once(document, f'<script defer src="{name}"></script>', "")
        scripts.append(f'<script data-source="{name}">\n{javascript}\n</script>')
    document = replace_once(document, "</body>", "\n".join(scripts) + "\n</body>")
    document = replace_once(
        document,
        "<!doctype html>",
        "<!doctype html>\n<!-- Generated by scripts/build_frontend.py; edit index.template.html, "
        "styles.css and app.js, then rebuild. -->\n<!-- Leaflet license:\n"
        + license_text
        + "\n-->",
    )
    return document


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if generated HTML is stale.")
    args = parser.parse_args()
    output = WEB / "index.html"
    document = bundle()
    if args.check:
        if not output.exists() or output.read_text() != document:
            parser.exit(1, "Frontend bundle is stale. Run python scripts/build_frontend.py.\n")
        print("Frontend bundle is current.")
    else:
        output.write_text(document)
        print(f"Built self-contained frontend ({len(document.encode()):,} bytes).")


if __name__ == "__main__":
    main()
